    "disponible": ("Disponibilidades / efectivo", ("efectivo y equivalentes", "disponibilidades")),
    "deudores": ("Deudores comerciales / créditos por ventas", ("deudores comerciales", "creditos por ventas")),
    "inventario": ("Inventarios / bienes de cambio", ("inventarios", "bienes de cambio")),
    "proveedores": ("Acreedores comerciales / deudas comerciales", ("acreedores comerciales", "deudas comerciales")),
    "intereses": ("Intereses perdidos", ("intereses perdidos",)),
