    "MB": ("Margen bruto", "Rentabilidad", "%", "mayor", "(Ventas − Costo de ventas) / Ventas × 100"),
    "MO": ("Margen operativo", "Rentabilidad", "%", "mayor", "Resultado operativo / Ventas × 100"),
    "MN": ("Margen neto", "Rentabilidad", "%", "mayor", "Resultado del ejercicio / Ventas × 100"),
    "ROA": ("Rentabilidad del activo (ROA)", "Rentabilidad", "%", "mayor",
            "Resultado anualizado / Activo promedio × 100"),
    "ROE": ("Rentabilidad del patrimonio (ROE)", "Rentabilidad", "%", "mayor",
            "Resultado anualizado / Patrimonio promedio × 100"),
    "EP": ("Endeudamiento sobre patrimonio", "Endeudamiento", "veces", "menor", "Pasivo / Patrimonio"),
