    # 7.6 (18/11/2026): análisis del EBITDA. EBITDA ajustado = resultado operativo + depreciaciones y amortizaciones
    # − otros ingresos + otros gastos (sin sus depreciaciones). «12 meses» = los últimos 12 meses a la fecha.
    "EBM": ("Margen EBITDA ajustado", "EBITDA", "%", "mayor", "EBITDA ajustado / Ventas × 100"),
    "EBC": ("Cobertura de intereses con EBITDA", "EBITDA", "veces", "mayor",
            "EBITDA de 12 meses / Intereses perdidos de 12 meses"),
    "EBD": ("Deuda financiera neta / EBITDA", "EBITDA", "veces", "menor",
            "(Deuda financiera − Efectivo y equivalentes) / EBITDA de 12 meses"),
