    "EBK": ("Conversión del EBITDA en caja", "EBITDA", "%", "mayor",
            "(EBITDA − Aumento del capital de trabajo operativo) / EBITDA × 100"),
    "EBG": ("Crecimiento del EBITDA", "EBITDA", "%", "mayor",
            "EBITDA ajustado / EBITDA ajustado del mismo período del año anterior × 100 − 100"),
