# Partida Doble — sistema contable didáctico (versión web)
# Copyright (C) 2026 Gustavo Duarte
# Licencia Pública General GNU (GPL), versión 3 o posterior (ver LICENSE).
"""Puente entre la página web y el núcleo contable de la versión de escritorio (sin cambios).

Cada función recibe y devuelve texto JSON. Los errores contables (ErrorContable) vuelven como
{"error": "mensaje"} para que la página los muestre tal cual: el mensaje también enseña."""
import json
import sqlite3
import time

from partidadoble.base import ErrorContable, fmt_fecha, parse_importe
from partidadoble.contabilidad import Contabilidad, fmt_importe
from partidadoble.db import conectar

ESTADO = {}
RUTA = "/tmp/empresa.db"


def _ctb():
    return ESTADO["ctb"]


def _respuesta(fn):
    """Envuelve una operación: devuelve su resultado en JSON o el mensaje del error contable."""
    def envoltura(*args):
        try:
            return json.dumps(fn(*args))
        except ErrorContable as e:
            return json.dumps({"error": str(e)})
    return envoltura


def abrir(ruta):
    t = time.time()
    con = conectar(ruta)          # migra la base si viene de una versión anterior, como el programa de escritorio
    ctb = Contabilidad(con)
    ESTADO.update(con=con, ctb=ctb)
    emps = [dict(id=e["id"], codigo=e["codigo"], nombre=e["nombre"], inicio=e["inicio_ejercicio"] or "",
                 cierre=e["cierre_ejercicio"] or "") for e in ctb.empresas()]
    n = con.execute("SELECT COUNT(*) FROM asientos").fetchone()[0]
    return json.dumps(dict(empresas=emps, asientos=n, segundos=round(time.time() - t, 3)))


def copia():
    """Copia consistente de la base para descargarla. Devuelve la ruta del archivo."""
    destino = "/tmp/copia.db"
    with sqlite3.connect(destino) as d:
        ESTADO["con"].backup(d)
    d.close()
    return destino


# --------------------------------------------------------------- configuración (solo lectura)
@_respuesta
def ficha(emp):
    e = _ctb().empresa(int(emp))
    campos = [("Código", "codigo"), ("Nombre", "nombre"), ("RUT", "rut"), ("Inicio del ejercicio", "inicio_ejercicio"),
              ("Cierre del ejercicio", "cierre_ejercicio"), ("Estructura del plan", "estructura"),
              ("Moneda nacional", "moneda_nacional")]
    claves = e.keys()
    filas = []
    for etiqueta, k in campos:
        if k in claves:
            v = e[k]
            if k.endswith("ejercicio") and v:
                v = fmt_fecha(v)
            filas.append([etiqueta, "" if v is None else str(v)])
    return dict(filas=filas)


@_respuesta
def plan(emp):
    filas = []
    for c in _ctb().cuentas(int(emp)):
        filas.append(dict(id=c["id"], codigo=c["codigo"], nombre=c["nombre"], nivel=c["nivel"],
                          imputable=bool(c["imputable"]), auxiliar=c["auxiliar"] or "", moneda=c["moneda"] or ""))
    return dict(cuentas=filas)


@_respuesta
def datos_asiento(emp):
    """Lo que necesita el editor de asientos: libros, locales, terceros y cuentas con movimiento."""
    emp = int(emp)
    ctb = _ctb()
    return dict(
        libros=[dict(id=l["id"], texto=f"{l['codigo']} · {l['nombre']}") for l in ctb.libros(emp)],
        locales=[dict(id=l["id"], texto=f"{l['codigo']} · {l['nombre']}") for l in ctb.locales(emp, True)],
        terceros=[dict(id=t["id"], tipo=t["tipo"], texto=f"{t['codigo']} · {t['nombre']}")
                  for t in ctb.terceros(emp, solo_activos=True)],
        cuentas=[dict(id=c["id"], codigo=c["codigo"], nombre=c["nombre"], auxiliar=c["auxiliar"] or "",
                      moneda=c["moneda"] or "") for c in ctb.cuentas(emp) if c["imputable"]],
        ultima=ctb.ultima_fecha(emp) or "")


# --------------------------------------------------------------- asientos
@_respuesta
def lista_asientos(emp, desde, hasta, buscar):
    filas = []
    for a in _ctb().asientos(int(emp), desde or None, hasta or None, None, buscar or None):
        filas.append(dict(id=a["id"], numero=a["numero"], fecha=fmt_fecha(a["fecha"]), libro=a["libro_cod"],
                          concepto=a["concepto"] or "", total=fmt_importe(a["total"] or 0), tipo=a["tipo"]))
    return dict(asientos=filas)


@_respuesta
def asiento(asiento_id):
    ctb = _ctb()
    a = ctb.asiento(int(asiento_id))
    lineas = [dict(cuenta=m["codigo"], nombre=m["nombre"], concepto=m["concepto"] or "",
                   debe=fmt_importe(m["debe"], vacio_si_cero=True), haber=fmt_importe(m["haber"], vacio_si_cero=True),
                   tercero_id=m["tercero_id"], tercero=(f"{m['ter_cod']} · {m['ter_nom']}" if m["ter_cod"] else ""),
                   moneda=m["moneda"] or "")
              for m in ctb.movimientos_de(a["id"])]
    return dict(id=a["id"], numero=a["numero"], fecha=a["fecha"], libro_id=a["libro_id"], local_id=a["local_id"],
                concepto=a["concepto"] or "", tipo=a["tipo"], lineas=lineas)


@_respuesta
def guardar(texto):
    """Registra (o modifica) un asiento con las mismas reglas del programa de escritorio."""
    p = json.loads(texto)
    ctb = _ctb()
    emp = int(p["emp"])
    lineas = []
    for i, l in enumerate(p["lineas"], 1):
        codigo = (l.get("cuenta") or "").split(" ")[0].strip()
        if not codigo and not (l.get("debe") or l.get("haber")):
            continue                      # renglón vacío
        cta = ctb.cuenta_por_codigo(emp, codigo)
        if not cta:
            raise ErrorContable(f"Línea {i}: no existe la cuenta «{codigo}». Elíjala de la lista.")
        if cta["moneda"]:
            raise ErrorContable(f"Línea {i}: la cuenta {cta['codigo']} {cta['nombre']} se lleva en {cta['moneda']}. "
                                "Las operaciones en moneda extranjera se registran, por ahora, en el programa de "
                                "escritorio.")
        debe, haber = parse_importe(l.get("debe")), parse_importe(l.get("haber"))
        if debe and haber:
            raise ErrorContable(f"Línea {i}: un renglón va al Debe o al Haber, no a los dos.")
        lineas.append(dict(cuenta_id=cta["id"], concepto=l.get("concepto") or "", debe=debe, haber=haber,
                           tercero_id=int(l["tercero_id"]) if l.get("tercero_id") else None))
    if not lineas:
        raise ErrorContable("El asiento no tiene renglones.")
    aid = ctb.guardar_asiento(emp, p["fecha"], int(p["libro_id"]) if p.get("libro_id") else None,
                              int(p["local_id"]) if p.get("local_id") else None, p.get("concepto") or "",
                              lineas, int(p["asiento_id"]) if p.get("asiento_id") else None)
    return dict(id=aid, numero=ctb.asiento(aid)["numero"])


@_respuesta
def eliminar(asiento_id):
    ctb = _ctb()
    a = ctb.asiento(int(asiento_id))
    ctb.eliminar_asiento(int(asiento_id))
    return dict(numero=a["numero"])


# --------------------------------------------------------------- consultas
def _celda(tipo, v):
    if v is None:
        return ""
    if tipo == "importe":
        return fmt_importe(v)
    if tipo == "fecha":
        try:
            return fmt_fecha(v)
        except (ValueError, AttributeError):
            return str(v)            # renglones como «Saldo anterior» llevan texto en la columna de fecha
    return str(v)


def informe(tipo, emp, desde, hasta, nivel, cuenta=""):
    t = time.time()
    try:
        ctb = _ctb().para_informes(emp, hasta, desde)
        nivel = int(nivel)
        if tipo == "balance":
            rep = ctb.balance_comprobacion(emp, desde, hasta, nivel)
        elif tipo == "situacion":
            rep = ctb.estado_situacion(emp, hasta, nivel)
        elif tipo == "resultados":
            rep = ctb.estado_resultados(emp, desde, hasta, nivel)
        elif tipo == "mayor":
            cta = ctb.cuenta_por_codigo(emp, (cuenta or "").split(" ")[0].strip())
            if not cta:
                raise ErrorContable("Elija la cuenta o el rubro del mayor.")
            rep = ctb.mayor(emp, cta["id"], desde, hasta)
        else:
            rep = ctb.libro_diario(emp, desde, hasta)
    except ErrorContable as e:
        return json.dumps({"error": str(e)})
    tipos = [c[1] for c in rep.columnas]
    datos = dict(titulo=rep.titulo, subtitulo=rep.subtitulo,
                 columnas=[[c[0], c[1]] for c in rep.columnas],
                 filas=[[f.estilo, f.nivel, [_celda(tp, v) for tp, v in zip(tipos, f.valores)]] for f in rep.filas],
                 notas=list(rep.notas))
    datos["segundos"] = round(time.time() - t, 3)
    return json.dumps(datos)
